    "https://www.yz.sdu.edu.cn/2025/shandongdaxue2025nianshuoshiyanjiushengzhaoshengzhuanyemulu.pdf#25#15",
    "https://www.cs.sdu.edu.cn/gyxy/xyjj.htm?ivk_sa=1024320u",
    "https://www.cs.sdu.edu.cn/zsxx/syjd.htm",
    "https://www.cs.sdu.edu.cn/info/1068/6855.htm",
    "https://yz.sdu.edu.cn/info/1022/1254.htm",
    "https://yz.chsi.com.cn/kyzx/kydt/202610/20261008/2293977251.html",
    "https://yz.chsi.com.cn/kyzx/kydt/202610/20261008/2293977279.html",
    "https://yz.chsi.com.cn/sch/viewZbBulletin--schId-369158,infoId-3551215697,categoryId-433376,mindex-10.dhtml",
    "https://yz.chsi.com.cn/sswbgg/pages/msgdetail.do?dwdm=11846&msg_id=654533"
  ],
  "recommendationNotice": "已指定目标院校为山东大学计算机相关专业，本方案不再推荐其他院校；请以山东大学研究生招生网和计算机科学与技术学院官网信息为准。",
  "recommendations": [],
  "tasks": [
    {
      "title": "核对山东大学2027年硕士招生专业目录中计算机相关专业的初试科目、研究方向与培养校区；确认自己是否符合应届本科报考条件，整理学信网学籍与报名材料清单。",
      "stage": "信息核对与基础",
      "dueDate": "2026-10-01"
    },
    {
      "title": "制定英语与数学补强周计划，英语每天安排词汇与长难句，数学从高数基础章节开始，完成一次基础自测并记录薄弱点。",
      "stage": "信息核对与基础",
      "dueDate": "2026-10-06"
    },
    {
      "title": "完成研招网报名信息核对，关注山东省报考点公告与预报名、正式报名时间；确认政治、英语一、数学一、408所需资料版本。",
      "stage": "信息核对与基础",
      "dueDate": "2026-10-11"
    },
    {
      "title": "整理408四门课考纲与教材目录，完成数据结构基础复习；英语开始每周两篇阅读精读，数学完成高数第一章至第二章基础题。",
      "stage": "信息核对与基础",
      "dueDate": "2026-10-17"
    },
    {
      "title": "强化数据结构与计算机组成原理交替复习，完成线性表、树、排序与处理器基础练习；数学进入线代基础，英语继续长难句与阅读。",
      "stage": "系统学习与强化",
      "dueDate": "2026-10-22"
    },
    {
      "title": "推进操作系统进程、内存、文件管理，配合408真题分章练习；数学完成线代核心题型，政治开始马原基础框架。",
      "stage": "系统学习与强化",
      "dueDate": "2026-10-27"
    },
    {
      "title": "计算机网络分层复习，重点TCP/IP、路由与网络安全；408完成一轮综合题；英语开始写作模板积累，数学进入概率基础。",
      "stage": "系统学习与强化",
      "dueDate": "2026-11-01"
    },
    {
      "title": "完成408四门课第一轮系统复习并整理错题本；政治完成马原、毛中特主干；数学完成一轮全科基础，英语做一套真题阅读并复盘。",
      "stage": "系统学习与强化",
      "dueDate": "2026-11-06"
    },
    {
      "title": "按套限时训练408近年真题，重点分析错题知识点；数学开始真题分题型训练；英语完成一篇大作文和小作文各一次。",
      "stage": "真题训练与查漏",
      "dueDate": "2026-11-12"
    },
    {
      "title": "政治进入选择题刷题与史纲、思修知识点串联；数学真题限时三小时一套并订正；408针对薄弱章节回看教材与笔记。",
      "stage": "真题训练与查漏",
      "dueDate": "2026-11-17"
    },
    {
      "title": "完成英语近年真题整套模拟，复盘阅读与翻译；政治完成选择题高频错题；数学整理常用公式与错题，408强化操作系统与网络。",
      "stage": "真题训练与查漏",
      "dueDate": "2026-11-22"
    },
    {
      "title": "进行408与数学第二次真题套卷，记录时间分配；英语保持每日阅读与写作，政治开始背诵核心分析题考点。",
      "stage": "真题训练与查漏",
      "dueDate": "2026-11-27"
    },
    {
      "title": "全科模拟一次，按考试时段安排政治、英语；核对山东大学专业目录与准考证信息；整理各科高频考点。",
      "stage": "模拟冲刺与调整",
      "dueDate": "2026-12-02"
    },
    {
      "title": "进行数学与408重点模拟，复盘失分点；英语准备作文模板并做翻译练习；政治完成时政与核心背诵。",
      "stage": "模拟冲刺与调整",
      "dueDate": "2026-12-08"
    },
    {
      "title": "按初试时间表进行两天全真模拟，调整作息；回看错题本与公式，确认考场文具、证件与准考证下载打印。",
      "stage": "模拟冲刺与调整",
      "dueDate": "2026-12-13"
    },
    {
      "title": "考试前一天只做轻量回顾，检查身份证、准考证、文具与考点路线；按考试时间早睡，保持平稳心态。",
      "stage": "模拟冲刺与调整",
      "dueDate": "2026-12-18"
    }
  ]
}
